#!/bin/bash
S1=$PWD/4_human_egm/share; mkdir -p $S1
cd 4_human_egm/project && cp -f txi.rsem.counts.txt $S1/human_EGM_counts.expected_count.tsv && cp -f txi.rsem.abundance.TPM.txt $S1/human_EGM_TPM.tsv && cp -f mapfile.tsv $S1/human_EGM_samplesheet.tsv && cp -f DESeq2_results_annotated.csv $S1/human_EGM_DESeq2_EGM_vs_Control.csv && cp -f Reference/hg38/gene_annotation.tsv $S1/human_gene_id_to_symbol.tsv && echo "human copied"
printf '%s\n' "Human bulk RNA-seq, Control (n=3) vs EGM (n=3), 101 bp PE, reverse-stranded (processed 2026-10-08)" "Pipeline: trim_galore 0.6 -> STAR 2.7.11b (Ensembl GRCh38 primary assembly + Ensembl 110 GTF, sjdbOverhang 100) -> RSEM 1.3.1 --strandedness reverse" "human_EGM_counts.expected_count.tsv : gene x sample RSEM expected_count (62,754 Ensembl gene ids)" "human_EGM_TPM.tsv : gene x sample RSEM TPM" "human_EGM_samplesheet.tsv : sample -> TREATMENT (untreated = Control, treated = EGM)" "human_EGM_DESeq2_EGM_vs_Control.csv : DESeq2 (R) EGM vs Control with gene_symbol column" "human_gene_id_to_symbol.tsv : Ensembl gene id -> symbol (Gene.ID, Gene.Name)" "Per-sample RSEM: 4_human_egm/project/<sample>.genes.results" > $S1/README.txt
for d in $S1; do (cd $d && md5sum *.tsv *.csv > md5sum.txt 2>/dev/null); done; chmod -R a+rX $S1
